const RewardsContent: React.FC<{ period: Period }> = ({ period }) => {
  const multiplier = PERIOD_MULTIPLIERS[period];
  const rewardsEth = DAILY_REWARDS_ETH * multiplier;
  const rewardsUsd = DAILY_REWARDS_USD * multiplier;

  const fmtEth = rewardsEth.toLocaleString("en-US", {
    maximumFractionDigits: 0,
  });
  const fmtUsd =
    rewardsUsd >= 1_000_000
      ? `${(rewardsUsd / 1_000_000).toFixed(1)}M`
      : `${Math.round(rewardsUsd / 1000)}K`;

  return (
    <Box
      css={{
        alignItems: "center",
        justifyContent: "space-between",
        display: "flex",
        width: "100%",
      }}
    >
      <Flex css={{ alignItems: "center", gap: "$2", whiteSpace: "nowrap" }}>
        <EthIcon size={20} />
        <Text
          variant="h4"
          css={{
            fontVariantNumeric: "tabular-nums",
            lineHeight: "32px",
            fontWeight: "$semibold",
          }}
        >
          {fmtEth}
        </Text>
      </Flex>
      <Text
        variant="h4"
        css={{
          color: "$muted",
          whiteSpace: "nowrap",
          fontVariantNumeric: "tabular-nums",
          lineHeight: "32px",
          fontWeight: "$regular",
        }}
      >
        ${fmtUsd}
      </Text>
    </Box>
  );
};

